import{c as t,Q as s,j as n,m as e}from"./chunks/framework.DOi4mjdC.js";const l="data:image/png;base64,",p="/assets/zh-cn_formulaimage_0000002353021272.D9YB7WIz.png",i="/assets/zh-cn_formulaimage_0000002352887900.dvjP1QkB.png",A=JSON.parse('{"title":"IsNan","description":"","frontmatter":{},"headers":[{"level":1,"title":"IsNan","slug":"isnan"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/数学计算/IsNan接口/IsNan.md","filePath":"api/SIMD-API/高阶API/数学计算/IsNan接口/IsNan.md"}'),o={name:"api/SIMD-API/高阶API/数学计算/IsNan接口/IsNan.md"};function d(r,a,c,h,g,u){return s(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="isnan" tabindex="-1">IsNan <a class="header-anchor" href="#isnan" aria-label="Permalink to &quot;IsNan&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>按元素判断输入的浮点数是否为nan，输出结果为浮点数或布尔值。当输出为浮点类型时，对于nan的输入数据，对应位置的结果为浮点类型的1，反之为0；当输出为bool类型时，对于nan的输入数据，对应位置的结果为true，反之为false。计算公式如下：</p><p><img src="'+l+'" alt=""></p><ul><li><p>当输出为浮点类型时：</p><p><img src="'+p+'" alt=""></p></li><li><p>当输出为bool类型时：</p><p><img src="'+i+`" alt=""></p></li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;const IsNanConfig&amp; config = DEFAULT_IS_NAN_CONFIG, typename T, typename U&gt;</span></span>
<span class="line"><span>__aicore__ inline void IsNan(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;U&gt;&amp; src, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const uint32_t count)</span></span></code></pre></div></li><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;const IsNanConfig&amp; config = DEFAULT_IS_NAN_CONFIG, typename T, typename U&gt;</span></span>
<span class="line"><span>__aicore__ inline void IsNan(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;U&gt;&amp; src, const uint32_t count)</span></span></code></pre></div></li></ul><p>由于该接口的内部实现中涉及精度转换。需要额外的临时空间来存储计算过程中的中间变量。临时空间支持开发者<strong>通过sharedTmpBuffer入参传入</strong>和<strong>接口框架申请</strong>两种方式。</p><ul><li>通过sharedTmpBuffer入参传入，使用该tensor作为临时空间进行处理，接口框架不再申请。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</li><li>接口框架申请临时空间，开发者无需申请，但是需要预留临时空间的大小。</li></ul><p>通过sharedTmpBuffer传入的情况，开发者需要为tensor申请空间；接口框架申请的方式，开发者需要预留临时空间。临时空间大小BufferSize的获取方式如下：通过<a href="./GetIsNanMaxMinTmpSize.html">GetIsNanMaxMinTmpSize</a>中提供的接口获取需要预留空间的大小。</p><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>IsNanConfig</td><td>IsNan算法的相关配置。此参数可选配，IsNanConfig类型，具体定义如下方代码所示，其中参数的含义为： isReuseSource：是否允许修改源操作数。该参数预留，传入默认值false即可。</td></tr><tr><td>T</td><td>目的操作数的数据类型。支持的数据类型为：bool、half、float。</td></tr><tr><td>U</td><td>源操作数的数据类型。支持的数据类型为：half、float。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct IsNanConfig {</span></span>
<span class="line"><span>    bool isReuseSource;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 目的操作数的数据类型和源操作数相同或者为bool类型。当前支持的数据类型组合请见表3。</td></tr><tr><td>src</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时缓存。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 用于IsNan内部复杂计算时存储中间变量，由开发者提供。 临时空间大小BufferSize的获取方式请参考GetIsNanMaxMinTmpSize。</td></tr><tr><td>count</td><td>输入</td><td>参与计算的元素个数。</td></tr></tbody></table><p><strong>表 3</strong> 输入输出支持的数据类型组合</p><table tabindex="0"><thead><tr><th>srcDtype</th><th>dstDtype</th></tr></thead><tbody><tr><td>half</td><td>half</td></tr><tr><td>half</td><td>bool</td></tr><tr><td>float</td><td>float</td></tr><tr><td>float</td><td>bool</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><strong>不支持源操作数与目的操作数地址重叠。</strong></li><li>操作数地址偏移对齐要求请参见<a href="./../../../通用说明和约束.html">通用说明和约束</a>。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>通过sharedTmpBuffer入参传入</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::TPipe pipe;</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::VECCALC, 1&gt; tmpQue;</span></span>
<span class="line"><span>pipe.InitBuffer(tmpQue, 1, bufferSize);  // bufferSize通过Host侧tiling参数获取</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;uint8_t&gt; sharedTmpBuffer = tmpQue.AllocTensor&lt;uint8_t&gt;();</span></span>
<span class="line"><span>// 输入tensor长度为1024, 算子输入的数据类型为half, 实际计算个数为512</span></span>
<span class="line"><span>static constexpr AscendC::IsNanConfig isNanConfig = { false }; // 不修改源操作数</span></span>
<span class="line"><span>// dst为bool类型的LocalTensor，src为half类型的LocalTensor</span></span>
<span class="line"><span>AscendC::IsNan&lt;isNanConfig, bool, half&gt;(dst, src, sharedTmpBuffer, 512);</span></span></code></pre></div></li><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::TPipe pipe;</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::VECCALC, 1&gt; tmpQue;</span></span>
<span class="line"><span>pipe.InitBuffer(tmpQue, 1, bufferSize);  // bufferSize通过Host侧tiling参数获取</span></span>
<span class="line"><span>// 输入tensor长度为1024, 算子输入的数据类型为half, 实际计算个数为512</span></span>
<span class="line"><span>static constexpr AscendC::IsNanConfig isNanConfig = { false }; // 不修改源操作数</span></span>
<span class="line"><span>// dst为bool类型的LocalTensor，src为half类型的LocalTensor</span></span>
<span class="line"><span>AscendC::IsNan&lt;isNanConfig, bool, half&gt;(dst, src, 512);</span></span></code></pre></div></li></ul><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入的数据类型为half，输出的数据类型为bool</span></span>
<span class="line"><span>输入数据(src):[1.0 nan 3.0 4.0 nan 6.0 nan 8.0]</span></span>
<span class="line"><span>输出数据(dst):[false true false false true false true false]</span></span></code></pre></div>`,28)])])}const m=t(o,[["render",d]]);export{A as __pageData,m as default};
